import{_ as r,a0 as p,w as i,s as u,I as s,x as l,a1 as e,A as n,ao as a}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const P=JSON.parse('{"title":"为什么你应该成为一名系统管理员？ | LCTT x X-CMD","titleTemplate":false,"description":"为什么你应该成为一名系统管理员？ | LCTT (201708) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"为什么你应该成为一名系统管理员？ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"为什么你应该成为一名系统管理员？ | LCTT (201708) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201708/20170717 Why you should be a sysadmin","title":"为什么你应该成为一名系统管理员？","tag":"201708","desc":""},"relativePath":"201708/20170717 Why you should be a sysadmin.md","filePath":"[post].md"}'),d={name:"201708/20170717 Why you should be a sysadmin.md"};function m(f,t,T,y,b,g){const o=p("Link");return i(),u("div",null,[t[19]||(t[19]=s("h1",{id:"为什么你应该成为一名系统管理员",tabindex:"-1"},[l("为什么你应该成为一名系统管理员？ "),s("a",{class:"header-anchor",href:"#为什么你应该成为一名系统管理员","aria-label":"Permalink to “为什么你应该成为一名系统管理员？”"},"​")],-1)),t[20]||(t[20]=s("blockquote",null,[s("p",null,"网络和系统管理工作工资高、岗位多。")],-1)),t[21]||(t[21]=s("p",null,[s("img",{src:"https://opensource.com/sites/default/files/styles/image-full-size/public/images/life/sysadmin_uncleserver.jpeg?itok=Tc9LAT7N",alt:"为什么你应该成为一名系统管理员",title:"Why you should be a sysadmin"})],-1)),t[22]||(t[22]=s("p",null,"我们为秩序而战，而服务器大叔则需要你成为系统管理员。",-1)),s("p",null,[t[1]||(t[1]=l("这是个很好的机会，因为你已经管理过你有的那些系统，你本可以不需酬劳地管理那些日逐一日地运行的系统。但还是有一些面试官，愿意拿一笔很不错的薪水来找一些人去管理他们的系统。目前，系统和网络管理的失业率几乎为零，但是美国劳工统计局估计到 2024 年该领域将持续 ",-1)),e(o,{href:"https://www.bls.gov/ooh/Computer-and-Information-Technology/Network-and-computer-systems-administrators.htm#tab-1"},{default:n(()=>[...t[0]||(t[0]=[l("9% 的增长",-1)])]),_:1}),t[2]||(t[2]=l("。",-1))]),t[23]||(t[23]=a('<p>你可能会问，自动化运维怎么样？大概你已经听一些系统管理员说过，他们打算如何来自动化他们所有的工作，或者，他们如何在一个 shell 脚本里自动化完成他们前任者的工作。你听过的有多少成功的？自动化了某个任务，就会有更多的东西需要自动化。</p><p>如果你参加过系统管理者会议或观看过他们的视频，你会发现这是一个需要新鲜血液的领域。不仅仅是明显的缺少年轻人，而且相当地性别和种族不平等。虽然有点儿跑题，但是多样性已经被证明可以提高系统管理员非常感兴趣的自我恢复力、解决问题的能力，创新力和决策力。</p><h3 id="我要成为一名系统管理员吗" tabindex="-1">我要成为一名系统管理员吗？ <a class="header-anchor" href="#我要成为一名系统管理员吗" aria-label="Permalink to “我要成为一名系统管理员吗？”">​</a></h3><p>有人要你，但是你要做系统管理工作吗？如果你生活在一个第一世界国家，每年 70,000 美元的收入看上去是一个可以感到幸福的标准收入，或者说至少减少了大部分的与钱相关的压力。系统和网络管理员的中位年度收入是 80,000 美元，很容易达标，尽管明显有些人赚的更少或更多。</p><p>你曾经免费做过一些系统管理工作吗？我们大多数人都多多少少地管理一些设备，但是那并不代表你喜欢管理它。如果你曾经在你家的网络中添加了一些服务器，你就是一个备选的系统管理员。你想要为自己的孩子添加一个“我的世界”的游戏服务器么，所以你用树莓派搭建了一个？也许是时候来考虑通过做这样的工作来获取报酬了。</p><p>作为一份需要全面知识的工作，系统管理工作有很大的跨度。各种行业和各种规模的公司都需要系统管理员。大多数的位于市区里的公司需要一些现场上班的人员，但是远程办公也有很大的可能性。</p><p>每个人都是免费地用开源软件工作，但是，作为系统管理员，你也可以计酬工作。系统管理员经常把对开源项目做贡献、支持开源供应商、使用各种各样的有趣而强大的开源软件为他们日常工作的一部分。</p><p>最后，谈一下社区。以我多年的经验来看，找到一个欢迎新人的、鼓励参与的、气氛友好的、彼此帮助的社区是非常难的。系统管理员给人的刻板印象就是性情乖戾，但是我感觉现在这只不过是个过时的笑话。现在大多数的系统管理员积极地回应各种形式的有建设性的反馈，尤其是欢迎新手。我们总是能敏锐的察觉到各种各样的入门级问题，并且热心于解决它们。我们是一个有深度的、兴趣广泛的社区。问一下一个系统管理员在工作之余都干了些什么，你肯定会感到吃惊。</p><h3 id="那么-我要从哪儿开始" tabindex="-1">那么，我要从哪儿开始？ <a class="header-anchor" href="#那么-我要从哪儿开始" aria-label="Permalink to “那么，我要从哪儿开始？”">​</a></h3><p>如果你被说服了，首先有个好消息。与许多技术类职业相比，从不是直接相关的四年制学历转为系统管理员是可能的。事实上，全世界有四年本科学历的系统管理员相对较少，所以不用太担心这个。对于现在的白领工作，学历确实有用，而且越相关越好。与其他的技术类职业相比，这儿有一个很自然的入门级别的职位：技术支持。</p><p>对系统管理工作的候选人来说有个坏消息是真的，在技术类领域（甚至非技术类领域）：雇主在寻找有多年经验的和有高学历的人，即便是在入门级别的岗位上。雇主是刻薄的，雇主不会花钱给你培训。不过稍嫌安慰的是，这些问题在人才市场上是非常普遍的，所以不管你找什么工作都得面对这种问题。</p><p>系统管理工作可以作为其他 IT 领域的起点。比如：网络管理、数据库管理、网站可靠性工程师（SRE），再远一些的也有，软件工程师、质量保证（QA）、IT 管理。</p><p>系统管理工作的具体情况，包括其刻板的印象和一些明显的方面以及不明显的方面，是未来我们的文章的主题。我们也会涵盖这个领域可能会改变的重要方面，提供一些方法来评估和比较系统管理职位，以及在面试中问到的一些重要问题。</p>',13)),s("p",null,[t[4]||(t[4]=l("如果你对加入这个领域有兴趣，可以考虑加入",-1)),e(o,{href:"https://lopsa.org/"},{default:n(()=>[...t[3]||(t[3]=[l("专业系统管理者联盟",-1)])]),_:1}),t[5]||(t[5]=l("（LOPSA），我在这个组织任董事会成员。会员资格是你负担得起的（可能由您的雇主负责），而学生免费。成为 LOPSA 会员，是找到同行们和与有各种经验、各种行业和工作环境中的人员讨论职业生涯的绝佳方式。",-1))]),t[24]||(t[24]=s("p",null,"（题图 : Jason Baker, CC BY-SA 4.0）",-1)),t[25]||(t[25]=s("hr",null,null,-1)),t[26]||(t[26]=s("p",null,"作者简介：",-1)),t[27]||(t[27]=s("p",null,"Paul English - 他是 PreOS 安全公司的首席执行官，也是专业系统管理员联盟的董事会成员，该专业系统管理员联盟是一个非营利性专业协会，从 2015 年至今致力于提升系统管理工作实践。 Paul 在 1998 年获得了伍斯特理工学院的计算机学士学位。自 1996 年以来，Paul 一直是 UNIX 和 Linux 系统管理员和许多场合冠以 IT 之名的那个人。最近他在管理一些系统管理员。",-1)),t[28]||(t[28]=s("hr",null,null,-1)),s("p",null,[t[7]||(t[7]=l("via: ",-1)),e(o,{href:"https://opensource.com/article/17/7/why-become-sysadmin"},{default:n(()=>[...t[6]||(t[6]=[l("https://opensource.com/article/17/7/why-become-sysadmin",-1)])]),_:1})]),s("p",null,[t[11]||(t[11]=l("作者：",-1)),e(o,{href:"https://opensource.com/users/penglish"},{default:n(()=>[...t[8]||(t[8]=[l("Paul English",-1)])]),_:1}),t[12]||(t[12]=l(" 译者：",-1)),e(o,{href:"https://github.com/sugarfillet"},{default:n(()=>[...t[9]||(t[9]=[l("sugarfillet",-1)])]),_:1}),t[13]||(t[13]=l(" 校对：",-1)),e(o,{href:"https://github.com/wxy"},{default:n(()=>[...t[10]||(t[10]=[l("wxy",-1)])]),_:1})]),s("p",null,[t[16]||(t[16]=l("本文由 ",-1)),e(o,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...t[14]||(t[14]=[l("LCTT",-1)])]),_:1}),t[17]||(t[17]=l(" 原创编译，",-1)),e(o,{href:"https://linux.cn/"},{default:n(()=>[...t[15]||(t[15]=[l("Linux中国",-1)])]),_:1}),t[18]||(t[18]=l(" 荣誉推出",-1))])])}const L=r(d,[["render",m]]);export{P as __pageData,L as default};
